"""Build the human-readable report and compact review tables from completed sweep."""
import sys as _delivery_sys
from pathlib import Path as _DeliveryPath
_delivery_sys.dont_write_bytecode = True
_delivery_root = next(parent for parent in _DeliveryPath(__file__).resolve().parents if (parent / 'models/source_layout.py').is_file())
if str(_delivery_root) not in _delivery_sys.path:
    _delivery_sys.path.insert(0, str(_delivery_root))
from models.source_layout import experiment_directory
from models.model_catalog import resolve_artifact as _resolve_model_artifact, artifact_glob as _model_artifact_glob, temporary_settings as _temporary_model_settings
from pathlib import Path
import json, sys
import pandas as pd
HERE = experiment_directory(__file__)
OUT = HERE / 'results'
a = pd.read_csv(_resolve_model_artifact(OUT / 'aggregate_equal_weight.csv'))
m = pd.read_csv(_resolve_model_artifact(OUT / 'metrics_by_match.csv'))
c = pd.read_csv(_resolve_model_artifact(OUT / 'changes_by_match.csv'))
t = pd.read_csv(_resolve_model_artifact(OUT / 'event_changes.csv'))
p = pd.read_csv(_resolve_model_artifact(OUT / 'added_false_alarms.csv'))
inventory = json.loads(_resolve_model_artifact(HERE / 'inventory.json').read_text(encoding='utf-8'))
validation = json.loads(_resolve_model_artifact(HERE / 'validation.json').read_text(encoding='utf-8'))
sessions = pd.read_csv(_resolve_model_artifact(HERE / 'manual_sessions.csv'))
conservative = sys.argv[1] if len(sys.argv) > 1 else 'minus_0.10'
recovery = sys.argv[2] if len(sys.argv) > 2 else 'minus_0.20'
chosen = ['original', conservative, recovery, 'argmax']
pv = a[a.scope == 'PV_heldout'].set_index('policy')
b = pv.loc['original']

def table(frame, cols):
    return frame[cols].to_string(index=False, float_format=lambda x: f'{x:.4f}')

def val(r, k):
    return float(r[k])
lines = ['M1-H2-D2: bajar el umbral de lineout', '22 de octubre de 2026', '', 'ALCANCE Y RESPUESTA', '', f'Se reevaluaron los seis partidos V_1–V_6, {sessions.blocks.sum()} bloques, {len(sessions)} secciones y {sessions.seconds.sum() / 3600:.4f} horas etiquetadas. No hubo entrenamiento, extracción ni inferencia de redes. Se conservaron probabilidades, pesos, etiquetas, umbrales de scrum y parámetros temporales.', f'La línea base reproduce exactamente el F1 temporal medio histórico: {b.mean_temporal_f1_macro:.9f}. Se verificaron todas las etiquetas e intervalos contra las 31 sesiones manuales. V_2 conserva {sessions.ignored_tail_seconds.sum():.3f} segundos de colas históricamente excluidas. Las tasas usan exclusivamente el tiempo etiquetado.', '', 'RESULTADOS PRINCIPALES (igual peso por partido)', 'Las sensibilidades, precisiones y F1 son medias aritméticas de las métricas de los seis partidos. TP, FP y FN son conteos enteros sumados. No se deduce la sensibilidad media dividiendo esos totales.', '']
for policy in chosen:
    r = pv.loc[policy]
    lines += [f'{policy}: TP {int(r.sum_line_tp)}/{int(r.sum_line_real)}, FP {int(r.sum_line_fp)}, FN {int(r.sum_line_fn)}. Precisión {r.mean_line_precision:.4f}, sensibilidad {r.mean_line_recall:.4f}, F1 por evento {r.mean_line_f1:.4f}. F1 temporal lineout {r.mean_line_temporal_f1:.4f}, scrum {r.mean_scrum_temporal_f1:.4f}, promedio ambas {r.mean_temporal_f1_macro:.4f}. FP lineout/h {r.mean_line_fp_per_hour:.3f}, FP lejanos lineout/h {r.mean_line_far_fp_per_hour:.3f}. FP totales ambas clases/h {r.mean_all_fp_per_hour:.3f}, lejanos ambas clases/h {r.mean_all_far_fp_per_hour:.3f}.']
    if policy != 'original':
        lines += [f'  Frente al original: {int(r.sum_line_recovered)} jugadas antes omitidas ahora tienen pareja y {int(r.sum_line_lost)} antes emparejadas la pierden. Cambio neto TP {int(r.sum_line_tp - b.sum_line_tp):+d}, FP {int(r.sum_line_fp - b.sum_line_fp):+d}. Nuevos FP sin solapamiento con un FP previo: {int(r.sum_line_new_fp_nonoverlap)}, FP previos sin solapamiento con FP actuales: {int(r.sum_line_removed_fp_nonoverlap)}. Candidatos que reúnen más de un candidato previo: {int(r.sum_line_merged_candidates)}. Los cambios de ancla, duración y emparejamiento están en los CSV.']
lines += ['', 'PROCEDENCIA, VERSIONES Y COBERTURA', '', 'La configuración principal es PV-M1-H2-D2, variante M1-100-H2, semilla 42, attempt_001 en los seis pliegues. Cada probabilidad se usa sólo con su modelo y su partido de prueba. Los hashes reales de dual.keras y geometry_rf.joblib coinciden con run.json y no cambiaron al finalizar.', 'Cada partido de prueba está fuera de los grupos CV de entrenamiento y de validación declarados de su pliegue. D2 incluye además los clips históricos CH y la inicialización histórica de H2. Esta revisión no establece nuevamente la independencia de los videos originales de todos esos clips. El barrido tampoco elimina el sesgo de haber seleccionado M1-H2-D2 entre configuraciones históricas.', 'Partido | Umbral original lineout | Umbral scrum | Validación | Entrenamiento CV | Bloques | Secciones']
for i in inventory:
    if i['scope'] == 'PV_heldout':
        lines += [f"{i['match']} | {i['thresholds']['line']:.2f} | {i['thresholds']['scrum']:.2f} | {i['development_group']} | {','.join(i['training_groups'])} | {i['blocks']} | {i['sections']}"]
lines += ['', 'VF se informa por separado: cuatro secciones de 20 minutos del mismo partido, modelo ALL-M1-H2-D2-S42 entrenado sobre los seis grupos V_1–V_6 y CH, alfa geométrica 0.475. No es un séptimo pliegue ni una repetición de la estimación 0.601. Se probaron sólo las probabilidades del modelo único, sin repetir ensembles. Los hashes de los dos pesos son idénticos en las cuatro secciones. Su independencia respecto de las fuentes históricas no está completamente verificada.', 'No se reconstruyó un partido VF completo: el análisis comparativo de referencia aporta S01–S04, mientras que S05 no tiene un archivo equivalente M1-single_quality_blocks.csv con probabilidades y etiquetas verificadas en esa campaña. Los resultados se agregan con igual peso por sección y no se mezclan con V_1–V_6.', '', 'REGLA RECONSTRUIDA Y ARGMAX', '', 'Umbrales originales: normalizar las tres probabilidades. Asignar lineout si p_line >= t_line y p_line/t_line >= p_scrum/t_scrum. Asignar scrum si p_scrum >= t_scrum y p_scrum/t_scrum > p_line/t_line. En otro caso, other. Lineout gana el empate de puntajes relativos. Other no compite directamente. No se exige que lineout sea argmax, de modo que bajar su umbral sí puede admitir bloques donde other tenga la probabilidad mayor. También cambia la competencia con scrum aunque su umbral numérico quede fijo.', 'Argmax se muestra como control separado: mayor probabilidad entre line, other y scrum, con el primer índice ante empate. No tiene umbral de aceptación. Por tanto, si se está mirando la variante argmax, hablar de bajar su umbral exige cambiar de política. El promedio histórico 0.600817 corresponde a umbrales por pliegue. La comparación VF del 17/10 incluye ambas reglas: en el modelo único, media temporal por sección 0.683928 con umbrales 0.50/0.45 y 0.743841 con argmax. Se reproducen aquí esos controles sin mezclar sus versiones.', 'Barrido: original, restar 0.05, 0.10, …, 0.65 al umbral de cada pliegue con piso 0.05, y multiplicar los originales por 0.75, 0.50 y 0.25 con el mismo piso. Cada política conserva el umbral original de scrum. Las reducciones grandes pueden producir el mismo umbral efectivo en varios pliegues. No se cambia ninguna otra regla.', '', 'EMPAREJAMIENTO Y MÉTRICAS', '', 'Un evento reúne bloques consecutivos de la misma clase dentro de cada sección. Las secciones se mantienen separadas como en el protocolo histórico, incluso al sumar el partido. La referencia real es el centro del intervalo real. La referencia predicha es el centro del primer bloque que alcanza la probabilidad máxima de la clase dentro del candidato.', 'Se conserva la asignación húngara uno a uno que maximiza el crédito temporal total dentro de la misma sección, con distancia máxima de 35 s. El crédito es max(0,1-distancia/35). Un emparejamiento exactamente a 35 s tiene crédito cero y sigue contado como pareja en los conteos enteros, como en la implementación original. Su cantidad se exporta. Esta asignación maximiza crédito, no necesariamente la cantidad de pares admisibles.', 'TP entero es la cantidad de parejas de esa asignación. FP es toda predicción sin pareja, incluidos duplicados cercanos. FN es toda referencia real sin pareja. Precisión = TP/candidatos, sensibilidad = TP/reales y F1 por evento = 2 TP/(reales+candidatos). El F1 temporal reemplaza TP por la suma de créditos y no debe llamarse tasa de detección.', 'FP lejano es un candidato sin pareja cuyo ancla queda a más de 35 s de todas las referencias de la misma clase y sección. Un duplicado cercano también es un FP total. Se informan ambas tasas por separado. Los candidatos y sus duraciones corresponden a segmentos para revisar, sin afirmar que toda su duración sea jugada real.', 'Recuperados/perdidos comparan la identidad fija de la referencia real antes y después del barrido. Nuevas falsas alarmas cuentan candidatos FP sin solapamiento con un FP original. Es una convención explícita de seguimiento, no el mismo valor que el aumento neto de FP. Una extensión o unión puede cambiar el ancla y el emparejamiento. Por eso la sensibilidad por evento puede caer aunque aumenten los bloques de lineout.', '', 'BARRIDO COMPLETO EN LOS SEIS PARTIDOS', '']
cols = ['policy', 'mean_line_threshold', 'sum_line_tp', 'sum_line_fp', 'sum_line_fn', 'mean_line_precision', 'mean_line_recall', 'mean_line_f1', 'mean_line_temporal_f1', 'mean_scrum_temporal_f1', 'mean_temporal_f1_macro', 'mean_line_fp_per_hour', 'mean_line_far_fp_per_hour', 'mean_all_fp_per_hour', 'mean_all_far_fp_per_hour']
lines += [table(a[a.scope == 'PV_heldout'], cols), '', 'DETALLE POR PARTIDO DE LAS OPCIONES DESTACADAS', '']
detail = m[(m.scope == 'PV_heldout') & m.policy.isin(chosen)]
compact = ['match', 'policy', 'line_threshold', 'scrum_threshold', 'line_real', 'line_tp', 'line_fp', 'line_fn', 'line_precision', 'line_recall', 'line_f1', 'line_temporal_f1', 'scrum_tp', 'scrum_fp', 'scrum_fn', 'scrum_temporal_f1', 'temporal_f1_macro', 'line_fp_per_hour', 'line_far_fp_per_hour', 'all_fp_per_hour', 'all_far_fp_per_hour', 'line_candidates', 'line_candidate_seconds']
detail[compact].to_csv(OUT / 'selected_options_by_match.csv', index=False)
lines += [table(detail, compact), '', 'CAMBIOS POR PARTIDO', '']
cdetail = c[(c.scope == 'PV_heldout') & c.policy.isin([conservative, recovery])]
lines += [table(cdetail, ['match', 'policy', 'line_recovered', 'line_lost', 'line_net_tp', 'line_net_fp', 'line_new_fp_nonoverlap', 'line_removed_fp_nonoverlap', 'line_merged_candidates', 'line_changed_candidates', 'line_net_fusions', 'scrum_to_line_blocks']), '', 'EJEMPLOS PARA REVISAR', 'Los tiempos son locales a la sección indicada. No son el reloj deportivo ni un tiempo de partido concatenado.', '']
for policy in [conservative, recovery]:
    for effect in ['recovered', 'lost']:
        g = t[(t.scope == 'PV_heldout') & (t.policy == policy) & (t.label == 'line') & (t.effect == effect)]
        lines += [f'{policy}, {effect}:', table(g.head(10), ['match', 'section', 'start_time', 'end_time', 'anchor_time', 'predicted_anchor_s'])]
    g = p[(p.scope == 'PV_heldout') & (p.policy == policy) & (p.label == 'line')]
    lines += [f'{policy}, falsas alarmas agregadas (sin FP anterior solapado):', table(g.head(10), ['match', 'section', 'start_time', 'end_time', 'anchor_time', 'status'])]
lines += ['', 'VF: DIAGNÓSTICO SEPARADO POR SECCIÓN', '', table(a[a.scope == 'VF_single_sections'], cols), '', 'SELECCIÓN Y RECOMENDACIÓN', '', 'Ninguna reducción ensayada mejora el F1 temporal promedio de los seis partidos frente al original. Tampoco mejora la media de F1 por evento de lineout. Recomiendo conservar los umbrales actuales para el criterio global. Restar 0.05 es una opción exploratoria moderada si se prioriza revisar menos omisiones y se acepta el costo de 26 FP adicionales por 7 recuperaciones. Restar 0.15 reduce las omisiones de 51 a 29, con 96 FP adicionales, y sirve sólo si ese volumen de revisión es aceptable.', 'El efecto es muy desigual. V_4 concentra 25 de las 51 omisiones originales, con umbral lineout 0.70: al bajar a 0.65 recupera 2 sin sumar FP, y al bajar a 0.55 pasa de 7 a 12 TP y de 2 a 4 FP. En V_5, bajar 0.05 sólo recupera 1 y suma 12 FP. Esto justifica estudiar calibración en validación por partido o dominio, pero no elegir un umbral distinto para cada prueba observando sus etiquetas.', 'Ejemplo de pérdida por unión: V_6, S04. El candidato original 12:36–12:43 detecta la referencia 12:36–12:50. Al restar 0.15 se une con otro candidato en 12:29–13:32. Su pico queda en 13:21.5, a 38.5 s del centro real 12:43.0, y pierde la pareja pese a que aumentó la cobertura de lineout. La sensibilidad media también cae de 0.9178 a 0.9066 al pasar de restar 0.35 a restar 0.40.', f'Las opciones destacadas son {conservative} (conservadora) y {recovery} (mayor recuperación). Se eligieron después de observar las etiquetas de prueba y sólo describen este conjunto. El barrido responde cuánto cambia aquí el comportamiento. No valida un nuevo umbral para partidos futuros.', 'No se pudo hacer la selección por validación y posterior evaluación de prueba: faltan las probabilidades de validación del mismo modelo en los seis pliegues. runner.py recibe development_probabilities en memoria para elegir los umbrales originales y sólo guarda predictions.csv de prueba. Cada archivo y ruta esperada faltante figura en inventory.json y validation.json. Usar las probabilidades de prueba de otro pliegue como validación sería incorrecto porque corresponderían a otros pesos. No se volvió a ejecutar inferencia para obtenerlas.', 'No se modifica la configuración de la aplicación ni se despliega el umbral exploratorio. Para una recomendación con estimación fuera de muestra hay que recuperar esas probabilidades de validación o generar únicamente las probabilidades faltantes con los mismos modelos congelados y un protocolo decidido antes de mirar otra prueba.', '', 'ARCHIVOS Y VERIFICACIÓN', '', 'analyze.py: reconstrucción, verificación y barrido. report.py: este informe y tabla compacta. config.json: reglas y grilla. inventory.json: modelos, hashes, particiones y archivos faltantes. manual_sessions.csv: cobertura y procedencia de etiquetas. validation.json: reproducción histórica y hashes antes/después.', 'results/metrics_by_match.csv: todas las métricas por partido y por sección VF. aggregate_equal_weight.csv: medias de igual peso y sumas enteras. changes_by_match.csv: diferencias y uniones. derived_predictions.csv.gz: decisiones derivadas con probabilidades e intervalos. candidate_events.csv.gz: candidatos, parejas, distancia y crédito. truth_event_changes.csv.gz: seguimiento de todas las referencias. event_changes.csv: recuperados y pérdidas. changed_candidates.csv y added_false_alarms.csv: ejemplos completos para revisión.', 'figures/sensitivity_false_alarms.png: sensibilidad, precisión y efectos temporales.', f"Verificación final: {validation['manual_blocks']} bloques manuales, control histórico reproducido y fuentes sin cambios = {validation['sources_unchanged']}. Tiempo del análisis {validation['analysis_seconds']:.2f} s. No es tiempo de inferencia."]
(HERE / 'reporte.txt').write_text('\n'.join(lines) + '\n', encoding='utf-8')
pd.DataFrame([dict(conservative=conservative, higher_recovery=recovery, exploratory=True)]).to_csv(HERE / 'selected_options.csv', index=False)
print('\n'.join(lines[:20]))
